-- 1. Create table
CREATE TABLE IF NOT EXISTS study_notes (
  id          TEXT PRIMARY KEY,
  exam_type   TEXT NOT NULL,
  department  TEXT NOT NULL,
  title       TEXT NOT NULL,
  content     TEXT NOT NULL
);

-- 2. Enable RLS + public read/write policy
ALTER TABLE study_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY IF NOT EXISTS "study_notes_public_access"
  ON study_notes FOR ALL USING (true) WITH CHECK (true);

